.fingerprint-info{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;color:#f3dba8;font-size:11px;font-weight:bold;letter-spacing:1px}
.fingerprint-console{position:relative;display:flex;align-items:center;justify-content:center;min-height:222px;overflow:hidden}
