.fingerprint-hand{width:137px;position:absolute;top:-6px;left:calc(50% + 30px);transform:translateY(-160px) rotate(17deg);opacity:0;pointer-events:none;z-index:3;filter:drop-shadow(4px 4px #0b1814)}
.fingerprint-hand svg{width:100%;display:block;image-rendering:pixelated}
.fingerprint-reader.scanning .fingerprint-hand{animation:fingerPress 1.3s ease-in-out forwards;opacity:1}
@keyframes fingerPress{0%{transform:translateY(-160px) rotate(17deg);opacity:0}22%{opacity:1}55%,72%{transform:translateY(-12px) rotate(17deg);opacity:1}100%{transform:translateY(-160px) rotate(17deg);opacity:0}}
.scan-line{display:none;position:absolute;left:0;right:0;top:0;height:5px;background:#c3ffdd;box-shadow:0 0 22px 8px #57d7ac5e;opacity:.9}
.fingerprint-reader.scanning .scan-line{display:block;animation:fingerprintScanning .5s linear infinite alternate}
@keyframes fingerprintScanning{from{transform:translateY(8px)}to{transform:translateY(106px)}}
.fingerprint-led{position:absolute;bottom:7px;left:9px;width:13px;height:13px;border:3px solid #15231a;border-radius:3px;background:#efbe55;box-shadow:0 0 6px #b8944a}
