@keyframes ledFlicker{from{background:#efbe55;box-shadow:none}to{background:#57e6b0;box-shadow:0 0 18px #66d7a1}}
.fingerprint-label{position:absolute;bottom:7px;font-size:8px;color:#faf0bf;letter-spacing:2px}
