/* Dialogs remain in the visible viewport, with one scroll area. */
html.modal-open{overflow:hidden}
.overlay{position:fixed;top:0;right:0;bottom:0;left:0;overflow:hidden;padding:12px}
.modal{flex:none;margin:auto;max-height:100%;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;scroll-padding-block:12px}
.modal:focus{outline:none}
@supports (padding:max(0px, 1px)){
 .overlay{padding:max(12px,env(safe-area-inset-top)) max(12px,env(safe-area-inset-right)) max(12px,env(safe-area-inset-bottom)) max(12px,env(safe-area-inset-left))}
}
@media(max-width:650px),(max-height:510px){
 .modal button{min-height:44px}
}

.taca-modal{max-width:620px}
.taca-modal .section-head{flex-wrap:wrap;gap:8px}
.taca-diary{margin:8px 0 12px;padding:8px 12px;border-left:3px solid #cda463;color:#f1dcba;font-size:.9em}
.taca-scene{position:relative;display:flex;align-items:center;justify-content:center;height:clamp(125px,33vh,240px);overflow:hidden;background:radial-gradient(ellipse at 50% 60%,#62503b,#26271e 75%);border:2px solid #847656}
.taca-scene img{display:block;object-fit:contain;max-width:100%;image-rendering:pixelated}
.taca-jugador{height:96%;width:72%;align-self:end;animation:taca-arrive .45s steps(5,end) both}
.taca-day-2 .taca-jugador{width:55%;margin-right:32%}
.taca-mesa,.taca-trofeo{position:absolute;width:86%;height:96%}
.taca-lapices{position:absolute;top:57%;left:56%;width:32%;height:25%;background:#63442d;border:2px solid #c59663;box-shadow:3px 3px #231b15}
.taca-lapices i{position:absolute;top:15%;width:6px;height:70%;background:#e8ac58;border:1px solid #3f2a19;box-shadow:2px 2px #43291c}
.taca-lapices i:first-child{left:15%}.taca-lapices i:nth-child(2){right:15%}
.taca-lapices b,.taca-ball{position:absolute;top:42%;left:49%;width:10px;height:10px;border-radius:100%;background:#fff1c8;border:1px solid #665133;box-shadow:1px 2px #221b16}
.taca-lapices.autogol b{animation:taca-autogol 1.35s steps(14,end) both}
.taca-score{position:absolute;top:8px;left:8px;padding:4px 7px;background:#201f18;color:#ffe6a6;border:1px solid #ceb178;font-weight:bold}
.taca-scored .taca-score{animation:taca-arrive .3s 1.15s both}
.taca-scored .taca-mesa{animation:taca-hide .2s 1.22s both}
.taca-trofeo{animation:taca-arrive .45s 1.35s steps(5,end) both}
.taca-shot-pass .taca-ball{animation:taca-pass 1.2s steps(16,end) both}
.taca-shot-shoot .taca-ball{animation:taca-shoot 1.2s steps(15,end) both}
.taca-speech{margin:12px 0}.taca-speech b{color:#f1ca81}
.taca-modal .btn-row button{min-height:44px}
@keyframes taca-arrive{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
@keyframes taca-autogol{0%{left:49%}48%{left:66%}100%{left:7%}}
@keyframes taca-hide{to{opacity:0}}
@keyframes taca-pass{0%{left:49%;top:42%}45%{left:43%;top:52%}94%{left:70%;top:37%;opacity:1}100%{left:70%;top:37%;opacity:0}}
@keyframes taca-shoot{0%{left:49%;top:42%}94%{left:70%;top:37%;opacity:1}100%{left:70%;top:37%;opacity:0}}
@media(prefers-reduced-motion:reduce){
 .taca-scene *{animation:none!important}
 .taca-scored .taca-mesa,.taca-scored .taca-ball{visibility:hidden}
}

